CREATE TABLE users (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'consumer',name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at TEXT NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'Other',spec TEXT NOT NULL DEFAULT '{}',status TEXT NOT NULL DEFAULT 'idea',demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE support (user_id TEXT NOT NULL REFERENCES users(id),product_id TEXT NOT NULL REFERENCES products(id),kind TEXT NOT NULL,price REAL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,product_id));
CREATE TABLE offers (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),manufacturer_id TEXT NOT NULL REFERENCES users(id),price REAL NOT NULL,currency TEXT NOT NULL DEFAULT 'USD',minimum_quantity INTEGER NOT NULL DEFAULT 1,terms TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE feedback (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),user_id TEXT NOT NULL REFERENCES users(id),version TEXT NOT NULL,kind TEXT NOT NULL,details TEXT NOT NULL,rating INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alerts (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),kind TEXT NOT NULL,severity TEXT NOT NULL,evidence_count INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events (id TEXT PRIMARY KEY,product_id TEXT NOT NULL REFERENCES products(id),actor_id TEXT NOT NULL REFERENCES users(id),from_status TEXT,to_status TEXT NOT NULL,note TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id TEXT PRIMARY KEY,offer_id TEXT NOT NULL REFERENCES offers(id),buyer_id TEXT NOT NULL REFERENCES users(id),paypal_order_id TEXT UNIQUE NOT NULL,status TEXT NOT NULL DEFAULT 'CREATED',amount REAL NOT NULL,currency TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE webhook_events (id TEXT PRIMARY KEY,event_type TEXT NOT NULL,received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit (id TEXT PRIMARY KEY,actor_id TEXT,action TEXT NOT NULL,subject_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_products_status ON products(status); CREATE INDEX idx_feedback_product ON feedback(product_id); CREATE INDEX idx_orders_buyer ON orders(buyer_id);
